select mn.*, p.P_Name as projectName, con.Con_Name as contractName,con.Con_Money_Total as contractTotalMoney, con.Con_Party_B_Id as contractCompanyId, c3.C_Name as contractCompanyName, con.Con_Bid_Amt AS contractControlPrice, c1.C_Name as sfaCostConsultantUnitName, c2.C_Name as sfaSupervisionUnitName from Settlement_First_Audit mn left join Pre_Project p on p.P_Id=mn.project_id left join Con_Contract con on con.Con_Id=mn.contract_id left join SYS_Company c1 on c1.C_Id=mn.sfa_cost_consultant_unit left join SYS_Company c2 on c2.C_Id=mn.sfa_supervision_unit left join SYS_Company c3 on c3.C_Id=con.Con_Party_B_Id
mn.status=1 and mn.del_flag=1
and mn.project_id in
#{item}
and mn.contract_id in
#{item}
and mn.sfa_cost_consultant_unit in
#{item}
and mn.sfa_supervision_unit in
#{item}
and mn.sfa_contract_price in
#{item}
and mn.sfa_supervision_unit_price in
#{item}
and mn.sfa_cost_consultant_unit_price in
#{item}
and mn.sfa_settlement_first_price in
#{item}
and mn.sfa_core_price in
